def countdown(n):
    while n > 0:
        yield n
        n -= 1

print(list(countdown(3)))

def first_even(nums):
    for n in nums:
        if n % 2 == 0:
            return n

def evens(nums):
    for n in nums:
        if n % 2 == 0:
            yield n

print(first_even([1, 2, 3, 4]), list(evens([1, 2, 3, 4])))

