class Squares:
    def __init__(self, limit):
        self.limit = limit
    def __iter__(self):
        self.n = 1
        return self
    def __next__(self):
        if self.n > self.limit:
            raise StopIteration
        result = self.n ** 2
        self.n += 1
        return result

print(list(Squares(3)))

class Count:
    def __init__(self, n):
        self.i, self.n = 0, n
    def __iter__(self):
        return self
    def __next__(self):
        if self.i >= self.n:
            raise StopIteration
        self.i += 1
        return self.i

c = Count(3)
print(list(c), list(c))

